WITH flattened AS (SELECT id, service, host, level, status_code, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS attr_key, value), flattened_attrs AS (SELECT id, service, level, attr_key, value, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 4) != 0 AS INT) AS is_flagged FROM flattened), with_windows AS (SELECT *, DENSE_RANK() OVER (PARTITION BY attr_key ORDER BY is_flagged DESC) AS is_flagged_dense_rank, PERCENT_RANK() OVER (PARTITION BY attr_key ORDER BY status_code_high DESC NULLS LAST) AS status_code_high_percent_rank, MIN(is_flagged) OVER (PARTITION BY level, service) AS level_min_is_flagged FROM flattened_attrs), with_windows_app_logs AS (SELECT *, SUM(status_code_high_percent_rank) OVER (PARTITION BY attr_key ORDER BY is_flagged_dense_rank ASC, id ASC, attr_key ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_sum_status_code_high_percent_rank, AVG(status_code_high_percent_rank) OVER (PARTITION BY attr_key ORDER BY is_flagged_dense_rank ASC, id ASC, attr_key ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_avg_status_code_high_percent_rank, MAX(status_code_high_percent_rank) OVER (PARTITION BY attr_key ORDER BY is_flagged_dense_rank ASC, id ASC, attr_key ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_max_status_code_high_percent_rank, FIRST_VALUE(level_min_is_flagged) IGNORE NULLS OVER (PARTITION BY attr_key ORDER BY status_code_high_percent_rank ASC, id ASC, attr_key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_level_min_is_flagged FROM with_windows), enriched AS (SELECT *, LEAD(is_flagged) OVER (PARTITION BY attr_key ORDER BY last7_avg_status_code_high_percent_rank ASC, id ASC, attr_key ASC) AS next_is_flagged, LAG(is_flagged) OVER (PARTITION BY attr_key ORDER BY last7_avg_status_code_high_percent_rank ASC, id ASC, attr_key ASC) AS prev_is_flagged, LAG(level_min_is_flagged) OVER (PARTITION BY attr_key ORDER BY last7_avg_status_code_high_percent_rank ASC, id ASC, attr_key ASC) AS prev_level_min_is_flagged, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY last7_avg_status_code_high_percent_rank ASC, id ASC, attr_key ASC) AS event_seq FROM with_windows_app_logs WHERE status_code_high > 1) SELECT level, CASE WHEN is_flagged_dense_rank >= 9 THEN 'HIGH' ELSE 'LOW' END AS is_flagged_dense_rank_tier, SIZE(COLLECT_SET(level)) AS num_levels, COUNT_IF(level = 'ERROR') AS error_events, APPROX_PERCENTILE(last7_avg_status_code_high_percent_rank, ARRAY(0.25, 0.5, 0.75)) AS last7_avg_status_code_high_percent_rank_quartiles, COUNT(*) AS event_count, SORT_ARRAY(COLLECT_SET(level)) AS level_list, PERCENTILE_APPROX(event_seq, 0.95) AS event_seq_p95 FROM enriched GROUP BY 1, 2 HAVING COUNT_IF(level = 'ERROR') < 1000 ORDER BY event_seq_p95 DESC NULLS LAST
